import type { OpenApiSchema } from "./types.js";

const VALID_IDENTIFIER_RE = /^[a-zA-Z_$][a-zA-Z0-9_$]*$/;
const PASCAL_IDENTIFIER_RE = /^[A-Z][a-zA-Z0-9_$]*$/;

const PRIMITIVE_TYPES = new Set([
  "string",
  "number",
  "boolean",
  "void",
  "unknown",
  "any",
  "never",
  "object",
  "Blob",
  "FormData",
]);

/** Header line written at the top of every generated file. */
export const GENERATED_HEADER = `// Auto-generated by swagger-layer from "./swagger.json"\n`;

export function toPascalCase(str: string): string {
  return str
    .replace(/[^a-zA-Z0-9]+(.)/g, (_, c: string) => c.toUpperCase())
    .replace(/^[a-z]/, (c: string) => c.toUpperCase());
}

export function toCamelCase(str: string): string {
  const pascal = toPascalCase(str);
  return pascal.charAt(0).toLowerCase() + pascal.slice(1);
}

export function toKebabCase(str: string): string {
  return str
    .replace(/([a-z0-9])([A-Z])/g, "$1-$2")
    .replace(/[\s_]+/g, "-")
    .toLowerCase();
}

export function cleanOperationId(opId: string): string {
  return opId.replace(/\d+$/, "");
}

export function resolveRef(ref: string): string {
  const parts = ref.split("/");
  return parts[parts.length - 1];
}

/** Name of the generated TypeScript enum for a schema (e.g. `UserRole` → `EUserRole`). */
export function toEnumTypeName(schemaName: string): string {
  return `E${schemaName}`;
}

/** TypeScript type name for a referenced schema, prefixing enums with `E`. */
export function refToTypeName(schemaName: string, enums: Set<string>): string {
  return enums.has(schemaName) ? toEnumTypeName(schemaName) : schemaName;
}

/** Sorted names of all schemas that define an `enum`. */
export function getEnumSchemaNames(schemas: Record<string, OpenApiSchema>): string[] {
  return Object.keys(schemas)
    .filter((name) => Array.isArray(schemas[name].enum))
    .sort();
}

export function formatPropertyKey(key: string): string {
  return VALID_IDENTIFIER_RE.test(key) ? key : JSON.stringify(key);
}

function normalizeModuleName(value: string): string {
  return toKebabCase(value).replace(/[-_]/g, "").toLowerCase();
}

export function isModuleExcluded(name: string, excludedModules: string[]): boolean {
  if (!name) return false;
  const target = normalizeModuleName(name);
  return excludedModules.some((ex) => normalizeModuleName(ex) === target);
}

export function cleanInterfaceImports(interfaces: Iterable<string>): string[] {
  return Array.from(new Set(interfaces))
    .filter((i) => !PRIMITIVE_TYPES.has(i) && PASCAL_IDENTIFIER_RE.test(i))
    .sort();
}

export function isPlainObject(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}
